/* Complete-sheet adapter. Existing combat_state JSON and cloud queue remain authoritative. */
const Studio={draft:null,busy:false,catalogType:'spells',catalogQuery:'',catalogClass:'',preview:null,undo:null,castResource:{}};
const stId=()=>crypto.randomUUID();
const stDev=()=>character.combat_state.development||{};
const stSnapshot=()=>LiorCharacter.clone({character,inventory,spells,companions,logs});
const stSignature=s=>{const copy=LiorCharacter.clone(s);delete copy.character.updated_at;return JSON.stringify(copy)};
const stSave=()=>{persist();renderAll()};
const stToday=()=>new Date().toISOString();
const stOption=(value,label,selected)=>`<option value="${esc(value)}" ${selected===value?'selected':''}>${esc(label)}</option>`;
function stField(id,label,value='',type='text',extra=''){
 return `<label>${esc(label)}${type==='textarea'?`<textarea id="${id}" ${extra}>${esc(value)}</textarea>`:`<input id="${id}" type="${type}" value="${esc(value)}" ${extra}>`}</label>`;
}
function stSelect(id,label,options,value){return `<label>${esc(label)}<select id="${id}">${options.map(([v,l])=>stOption(v,l,value)).join('')}</select></label>`}
const stValue=id=>document.getElementById(id)?.value||'';
const stNumber=id=>Number(stValue(id));
function stModal(title,html,save){
 document.getElementById('modalTitle').textContent=title;document.getElementById('modalBody').innerHTML='<div class="studio-form">'+html+'</div>';
 const button=document.getElementById('modalSaveBtn');button.hidden=!save;button.disabled=false;button.textContent='Guardar cambios';
 button.onclick=async()=>{if(Studio.busy)return;try{Studio.busy=true;button.disabled=true;await save()}catch(e){toast(e.message)}finally{Studio.busy=false;button.disabled=false}};
 document.getElementById('editorModal').classList.remove('hidden');
}
const stOldClose=closeModal;closeModal=function(){document.getElementById('modalSaveBtn').hidden=false;stOldClose()};
function stRequireReady(){if(typeof CloudSheet!=='undefined'&&(!CloudSheet.ready||CloudSheet.loading||CloudSheet.error==='conflict'))throw Error('Espera a que la ficha termine de cargar y resuelve cualquier conflicto de guardado.');}
function stHistory(text,details={}){
 character.combat_state.development||={};const d=character.combat_state.development;d.history||=[];d.history.unshift({id:stId(),date:stToday(),text,...details});
}
function stClassLabel(key){return LiorCharacter.labels[key]||key}
function stModifiers(){return(stDev().features||[]).filter(x=>x.active&&x.mechanics?.effect==='buff').reduce((a,x)=>{for(const k of ['attack','damage','ac'])a[k]+=Number(x.mechanics[k]||0);return a},{attack:0,damage:0,ac:0})}

function stCatalog(type='spells'){
 Studio.catalogType=type;Studio.catalogQuery='';Studio.catalogClass='';
 stModal('Catálogos y opciones de mesa',`<p>Catálogo SRD 2014: 319 conjuros, 237 objetos, 12 clases y sus rasgos. Los nombres y textos de referencia del SRD están en inglés. Las opciones de suplementos y del DM pueden añadirse con sus editores; no se inventan requisitos ni reglas.</p><div class="studio-grid">${stSelect('stCatType','Catálogo',[['spells','Conjuros de todas las clases'],['equipment','Armas y equipo'],['features','Rasgos e invocaciones'],['feats','Dotes SRD']],type)}${stSelect('stCatClass','Clase de origen',[['','Todas'],...Object.entries(LiorCharacter.names).map(([k,v])=>[v,stClassLabel(k)])],'')}${stField('stCatSearch','Buscar por nombre o texto','','search')}</div><div id="stCatalogRows"></div><p class="battle-subtext">Consultar no modifica tu ficha. Añadir abre un editor para revisar el origen y la mecánica antes de guardar.</p>`,null);
 for(const id of ['stCatType','stCatClass','stCatSearch'])document.getElementById(id).addEventListener(id==='stCatSearch'?'input':'change',stCatalogRows);
 stCatalogRows();
}
function stCatalogRows(){
 const type=stValue('stCatType'),q=stValue('stCatSearch').trim().toLowerCase(),cls=stValue('stCatClass');
 const all=LiorCatalog[type]||[];const rows=all.filter(x=>(!cls||(x.classes||[]).some(c=>c.index===cls)||x.class?.index===cls)&&(!q||(x.name+' '+(x.desc||[]).join(' ')).toLowerCase().includes(q)));
 document.getElementById('stCatalogRows').innerHTML=`<p>${rows.length} resultados · se muestran hasta 40. Usa el buscador para acotar.</p>`+rows.slice(0,40).map(x=>`<article class="studio-row"><div><strong>${esc(x.name)}</strong><small>${esc(type==='spells'?'Nivel '+x.level+' · '+x.classes.map(c=>c.name).join(', '):x.class?.name||x.equipment_category?.name||'SRD 2014')}</small><details><summary>Consultar referencia</summary><p>${esc((x.desc||[]).join('\n')||JSON.stringify(x.damage||x.properties||''))}</p></details></div><button class="quiet-btn" data-st-add="${esc(x.index)}" data-st-type="${type}">Añadir / configurar</button></article>`).join('');
 document.querySelectorAll('[data-st-add]').forEach(b=>b.onclick=()=>stAddCatalog(b.dataset.stType,b.dataset.stAdd));
}
function stExistingSpell(index,name){return spells.find(s=>s.catalog_index===index||s.name.toLowerCase()===name.toLowerCase()||s.name.toLowerCase().includes('('+name.toLowerCase()+')'))}
function stAddCatalog(type,index){
 const x=LiorCatalog[type].find(x=>x.index===index);if(!x)return;
 if(type==='spells'){
   const existing=stExistingSpell(index,x.name);if(existing)return openSpellModal(existing.id);
   const damage=x.damage?.[0],formula=damage?.damage_at_slot_level?.[x.level]||damage?.damage_at_character_level?.[1]||'';
   stSpellEditor(null,{name:x.name,level:x.level,class_origin:x.classes.map(c=>c.name).join(' / '),casting_time:x.casting_time.replace('bonus action','acción adicional').replace('reaction','reacción').replace('action','acción'),range_info:x.range,duration:x.duration,concentration:x.concentration,damage_dice:formula,damage_type:damage?.damage_type?.name||'',description:x.desc.concat(x.higher_level||[]).join('\n'),catalog_index:x.index,srd:x,is_known:true,is_equipped:true});
 }else if(type==='equipment'){
   const cat=x.equipment_category.index,existing=inventory.find(i=>i.catalog_index===index);if(existing)return openItemModal(existing.id);
   stItemEditor(null,{name:x.name,category:cat==='weapon'?'arma':cat==='armor'?(x.armor_category==='Shield'?'escudo':'armadura'):cat==='tools'?'herramienta':'objeto',subcategory:x.weapon_category||x.armor_category||x.equipment_category.name,damage_dice:x.damage?.damage_dice||'',damage_type:x.damage?.damage_type?.name||'',properties:(x.properties||[]).map(p=>({finesse:'Sutil',loading:'De carga',ammunition:'Munición',thrown:'Arrojadiza',versatile:'Versátil'}[p.index]||p.name)).join(', '),ac_bonus:x.armor_class?.base||0,magic_bonus:0,quantity:1,is_carried:true,is_equipped:false,range_info:x.range?x.range.normal+(x.range.long?'/'+x.range.long:'')+' pies':'',catalog_index:x.index,notes:(x.desc||[]).join('\n'),srd:x});
 }else stFeatureEditor(null,{name:x.name,description:x.desc.join('\n'),source:'SRD 2014 · '+(x.class?.name||'Dote'),catalog_index:index,resolution:'reference',kind:type==='feats'?'feat':'feature'});
}

function stSpellEditor(id=null,seed=null){
 const sp=LiorCharacter.clone(spells.find(s=>s.id===id)||seed||{name:'',level:1,class_origin:'Concesión del DM',casting_time:'1 acción',damage_dice:'',is_known:true,is_equipped:true});
 const m=sp.mechanics||{},resourceOpts=(stDev().resources||[]).map(r=>[r.id,r.name]);
 stModal(id?'Editar conjuro y funcionamiento':'Añadir conjuro de cualquier origen',`<div class="studio-grid">${stField('stSpName','Nombre',sp.name)}${stField('stSpLevel','Nivel (0 = truco)',sp.level,'number','min="0" max="9"')}${stField('stSpOrigin','Clase, objeto o concesión',sp.class_origin)}${stField('stSpApproval','Acuerdo / procedencia',m.source||'')}${stSelect('stSpAbility','Atributo de lanzamiento',['cha','int','wis','str','dex','con'].map(k=>[k,k.toUpperCase()]),m.ability||'cha')}${stSelect('stSpAction','Tiempo de lanzamiento',[['action','Acción'],['bonus','Acción adicional'],['reaction','Reacción'],['free','Sin acción / especial']],m.action||(/adicional|bonus/.test(sp.casting_time)?'bonus':/reacci/.test(sp.casting_time)?'reaction':'action'))}${stField('stSpRange','Alcance',sp.range_info)}${stField('stSpDuration','Duración',sp.duration)}${stSelect('stSpKind','Resolución',[['reference','Referencia / efecto manual'],['attack','Tirada de ataque'],['save','Salvación del objetivo'],['heal','Curación'],['temp','PG temporales']],m.kind||(sp.srd?.attack_type||/descarga sobrenatural|eldritch blast|toque helado|chill touch|infligir heridas|inflict wounds/i.test(sp.name)?'attack':sp.srd?.dc?'save':'reference'))}${stField('stSpDice','Fórmula base',sp.damage_dice)}${stSelect('stSpScaling','Escalado de la fórmula',[['auto','Normal del conjuro / SRD'],['fixed','Fórmula fija del DM · sin escalado automático']],m.scaling||'auto')}${stField('stSpDamageType','Tipo de daño / efecto',sp.damage_type)}${stField('stSpCount','Impactos / rayos (0 = escala de Descarga)',m.count??(/descarga sobrenatural|eldritch blast/i.test(sp.name)?0:1),'number','min="0" max="20"')}${stField('stSpAttackBonus','Bono adicional al ataque / CD',m.attackBonus||0,'number')}${stField('stSpFlat','Bono fijo al daño',m.flat||0,'number')}${stSelect('stSpPool','Cómo se paga',[['auto','Pacto o espacios normales'],['pact','Solo espacios de pacto'],['standard','Solo espacios normales'],['uses','Usos propios'],['resource','Reserva compartida'],['atwill','A voluntad · concesión explícita']],m.pool||'auto')}${stField('stSpMax','Usos propios máximos',m.max??1,'number','min="0"')}${stField('stSpUsed','Usos propios gastados',m.used??0,'number','min="0"')}${stSelect('stSpRecovery','Recupera usos',[['long','Descanso largo'],['short','Descanso corto o largo'],['manual','Solo manual']],m.recovery||'long')}${stSelect('stSpResource','Reserva compartida',[['','Seleccionar'],...resourceOpts],m.resource||'')}${stField('stSpCost','Coste en esa reserva',m.cost??1,'number','min="1"')}${stField('stSpCastLevel','Nivel al usar concesión (0 = nivel base)',m.castLevel||0,'number','min="0" max="9"')}${stSelect('stSpSave','Salvación del objetivo',['dex','wis','con','str','int','cha'].map(k=>[k,k.toUpperCase()]),m.save||sp.srd?.dc?.dc_type?.index||'dex')}</div><div class="studio-checks"><label><input type="checkbox" id="stSpKnown" ${sp.is_known?'checked':''}> Conocido / concedido</label><label><input type="checkbox" id="stSpFav" ${sp.is_equipped?'checked':''}> Favorito en combate</label><label><input type="checkbox" id="stSpConc" ${sp.concentration?'checked':''}> Concentración</label><label><input type="checkbox" id="stSpAbilityDamage" ${m.addAbility?'checked':''}> Añadir atributo al daño (solo si corresponde)</label></div>${stField('stSpDesc','Descripción y condiciones',sp.description||'','textarea')}<p>No se cambia ningún otro conjuro. Los efectos narrativos, áreas, salvaciones y condiciones se resuelven en la mesa; el gasto se registra aquí.</p>`,()=>{
   const name=stValue('stSpName').trim(),level=stNumber('stSpLevel'),max=stNumber('stSpMax'),used=stNumber('stSpUsed'),dice=stValue('stSpDice').trim(),pool=stValue('stSpPool');
   if(!name||!Number.isInteger(level)||level<0||level>9)throw Error('Revisa nombre y nivel del conjuro.');
   if(!Number.isInteger(max)||max<0||!Number.isInteger(used)||used<0||used>max)throw Error('Revisa los usos propios.');
   if(['attack','heal','temp'].includes(stValue('stSpKind'))&&dice&&!LiorDamage.dice(dice))throw Error('La fórmula debe usar dados y números, por ejemplo 2d6+3.');
   if(pool==='resource'&&!resourceOpts.some(([id])=>id===stValue('stSpResource')))throw Error('Selecciona una reserva compartida.');
   stRequireReady();const updated={...sp,id:id||stId(),character_id:character.id,name,level,class_origin:stValue('stSpOrigin'),casting_time:{action:'1 acción',bonus:'1 acción adicional',reaction:'1 reacción',free:'Especial'}[stValue('stSpAction')],range_info:stValue('stSpRange'),duration:stValue('stSpDuration'),damage_dice:dice,damage_type:stValue('stSpDamageType'),description:stValue('stSpDesc'),is_known:document.getElementById('stSpKnown').checked,is_equipped:document.getElementById('stSpFav').checked,concentration:document.getElementById('stSpConc').checked,
   mechanics:{...m,version:1,scaling:stValue('stSpScaling'),ability:stValue('stSpAbility'),action:stValue('stSpAction'),kind:stValue('stSpKind'),pool,max,used,recovery:stValue('stSpRecovery'),resource:stValue('stSpResource'),cost:stNumber('stSpCost'),castLevel:stNumber('stSpCastLevel'),attackBonus:stNumber('stSpAttackBonus'),flat:stNumber('stSpFlat'),count:stNumber('stSpCount'),addAbility:document.getElementById('stSpAbilityDamage').checked,save:stValue('stSpSave'),source:stValue('stSpApproval')}};
   if(updated.is_equipped&&!updated.is_known)throw Error('Un conjuro favorito debe estar conocido o concedido.');
   if(id)spells=spells.map(s=>s.id===id?updated:s);else spells.unshift(updated);stHistory((id?'Editado':'Añadido')+' conjuro: '+name);closeModal();stSave();
 });
}
openSpellModal=stSpellEditor;

function stItemEditor(id=null,seed=null){
 const item=LiorCharacter.clone(inventory.find(x=>x.id===id)||seed||{name:'',category:'arma',damage_dice:'1d8',quantity:1,is_carried:true});const m=item.mechanics||{};
 stModal(id?'Editar equipo y reglas de uso':'Añadir equipo / arma del DM',`<div class="studio-grid">${stField('stItName','Nombre',item.name)}${stSelect('stItCat','Categoría',[['arma','Arma'],['armadura','Armadura'],['escudo','Escudo'],['herramienta','Herramienta'],['objeto','Objeto']],item.category)}${stField('stItSub','Subcategoría',item.subcategory)}${stField('stItQty','Cantidad',item.quantity??1,'number','min="0"')}${stField('stItDice','Dados de daño',item.damage_dice)}${stField('stItType','Tipo de daño',item.damage_type)}${stField('stItMagic','Bono mágico',item.magic_bonus||0,'number')}${stField('stItAC','CA base / bono de escudo',item.ac_bonus||0,'number')}${stField('stItRange','Alcance',item.range_info)}${stField('stItProps','Propiedades',item.properties)}${stSelect('stItAbility','Atributo al atacar',[['auto','Normal del arma'],...['str','dex','con','int','wis','cha'].map(k=>[k,k.toUpperCase()])],m.ability||(item.use_cha?'cha':'auto'))}${stField('stItAttack','Bono adicional al ataque',m.attackBonus||0,'number')}${stField('stItFlat','Bono adicional al daño',m.flat||0,'number')}${stSelect('stItAmmo','Munición',[['','Sin gasto'],['ammo_pistol','Balas de pistola'],['ammo_musket','Balas de mosquete'],['quantity','Cantidad de este objeto']],m.ammo||(item.uses_ammo?(/mosquete|musket/i.test(item.name)?'ammo_musket':'ammo_pistol'):''))}${stField('stItSource','Origen / permiso del DM',m.source||item.source_note||'')}</div><div class="studio-checks">${[['stItCarry','Lo llevo',item.is_carried],['stItEquip','Equipado',item.is_equipped],['stItPact','Arma del pacto',item.is_pact_weapon],['stItProf','Soy competente',m.proficient!==false],['stItLoading','Ignorar De carga por concesión / dote',item.ignore_loading]].map(([id,label,on])=>`<label><input id="${id}" type="checkbox" ${on?'checked':''}> ${label}</label>`).join('')}</div>${stField('stItNotes','Descripción y reglas de mesa',item.notes||'','textarea')}${item.dm_rules?`<details><summary>Reglas especiales del arpón</summary>${stField('stItSlow','Reducción de velocidad',item.dm_rules.slow,'number')}${stField('stItUntil','Termina al…',item.dm_rules.slow_until)}${stField('stItWithdraw','Daño de extracción',item.dm_rules.withdraw_dice)}${stSelect('stItWithdrawCost','Coste de extracción',[['action','Acción'],['bonus','Acción adicional']],item.dm_rules.withdraw_cost)}${stField('stItDC','CD de extracción (vacío = DM)',item.dm_rules.withdraw_dc||'','number')}${stField('stItStatus','Acuerdo del DM',item.dm_rules.withdraw_status)}</details>`:''}`,()=>{
   const name=stValue('stItName').trim(),qty=stNumber('stItQty');if(!name||!Number.isInteger(qty)||qty<0)throw Error('Revisa nombre y cantidad.');
   if(stValue('stItCat')==='arma'&&!LiorDamage.dice(stValue('stItDice')))throw Error('Revisa los dados del arma.');
   stRequireReady();const updated={...item,id:id||stId(),name,category:stValue('stItCat'),subcategory:stValue('stItSub'),quantity:qty,damage_dice:stValue('stItDice'),damage_type:stValue('stItType'),magic_bonus:stNumber('stItMagic'),ac_bonus:stNumber('stItAC'),range_info:stValue('stItRange'),properties:stValue('stItProps'),notes:stValue('stItNotes'),is_carried:document.getElementById('stItCarry').checked,is_equipped:document.getElementById('stItEquip').checked,is_pact_weapon:document.getElementById('stItPact').checked,ignore_loading:document.getElementById('stItLoading').checked,use_cha:stValue('stItAbility')==='cha',mechanics:{...m,version:1,ability:stValue('stItAbility'),proficient:document.getElementById('stItProf').checked,attackBonus:stNumber('stItAttack'),flat:stNumber('stItFlat'),ammo:stValue('stItAmmo'),source:stValue('stItSource')}};
   if(updated.is_pact_weapon){updated.is_carried=false;updated.is_equipped=false}else if(updated.is_equipped)updated.is_carried=true;
   if(item.dm_rules){if(!LiorDamage.dice(stValue('stItWithdraw')))throw Error('Revisa la fórmula de extracción.');updated.dm_rules={...item.dm_rules,slow:stNumber('stItSlow'),slow_until:stValue('stItUntil'),withdraw_dice:stValue('stItWithdraw'),withdraw_cost:stValue('stItWithdrawCost'),withdraw_dc:stValue('stItDC')?stNumber('stItDC'):null,withdraw_status:stValue('stItStatus')}}
   if(id)inventory=inventory.map(i=>i.id===id?updated:i);else inventory.unshift(updated);stHistory((id?'Editado':'Añadido')+' equipo: '+name);closeModal();stSave();
 });
}
openItemModal=stItemEditor;

function stResourceEditor(id=null){
 const r=stDev().resources?.find(x=>x.id===id)||{name:'',max:1,used:0,recovery:'long'};
 stModal('Reserva compartida / cargas',`<div class="studio-grid">${stField('stRName','Nombre',r.name)}${stField('stRMax','Máximo',r.max,'number','min="0"')}${stField('stRUsed','Gastados',r.used,'number','min="0"')}${stSelect('stRRest','Recuperación',[['long','Descanso largo'],['short','Corto o largo'],['manual','Manual']],r.recovery)}${stField('stRSource','Origen',r.source||'')}</div>`,()=>{const max=stNumber('stRMax'),used=stNumber('stRUsed'),name=stValue('stRName').trim();if(!name||!Number.isInteger(max)||!Number.isInteger(used)||used<0||max<used)throw Error('Revisa nombre, máximo y gasto.');stRequireReady();character.combat_state.development||={};const d=character.combat_state.development;d.resources||=[];const next={...r,id:id||stId(),name,max,used,recovery:stValue('stRRest'),source:stValue('stRSource')};d.resources=id?d.resources.map(x=>x.id===id?next:x):d.resources.concat(next);stHistory('Reserva configurada: '+name);closeModal();stSave()});
}
function stFeatureEditor(id=null,seed=null){
 const f=LiorCharacter.clone(stDev().features?.find(x=>x.id===id)||seed||{name:'',description:'',source:'Concesión del DM',resolution:'reference'}),m=f.mechanics||{};
 stModal('Rasgo, dote o capacidad de cualquier origen',`<div class="studio-grid">${stField('stFName','Nombre',f.name)}${stField('stFSource','Origen / acuerdo del DM',f.source)}${stSelect('stFKind','Tipo',[['feature','Rasgo / capacidad'],['feat','Dote'],['proficiency','Competencia / idioma / herramienta']],f.kind||'feature')}${stSelect('stFEffect','Funcionamiento',[['reference','Solo referencia'],['buff','Efecto activable: bonos'],['damage','Referencia de daño'],['heal','Curar a Lior'],['temp','PG temporales a Lior']],m.effect||'reference')}${stSelect('stFCost','Acción al usar',[['free','Sin acción'],['action','Acción'],['bonus','Acción adicional'],['reaction','Reacción']],m.action||'free')}${stField('stFMax','Usos propios (0 = ilimitado)',m.max||0,'number','min="0"')}${stField('stFUsed','Usos gastados',m.used||0,'number','min="0"')}${stSelect('stFRest','Recuperación',[['long','Descanso largo'],['short','Corto o largo'],['manual','Manual']],m.recovery||'long')}${stSelect('stFResource','Reserva compartida (opcional)',[['','Usos propios'],...(stDev().resources||[]).map(r=>[r.id,r.name])],m.resource||'')}${stField('stFResourceCost','Coste de reserva',m.cost||1,'number','min="1"')}${stField('stFDice','Dados de efecto',m.dice||'')}${stField('stFAttack','Bono al ataque mientras esté activo',m.attack||0,'number')}${stField('stFDamage','Bono al daño mientras esté activo',m.damage||0,'number')}${stField('stFAC','Bono a CA mientras esté activo',m.ac||0,'number')}${stField('stFDuration','Duración en turnos (0 = manual)',m.duration||0,'number','min="0"')}</div>${stField('stFDesc','Descripción, requisitos y elecciones',f.description,'textarea')}<p>Solo los efectos configurados se aplican automáticamente. La referencia conserva íntegramente los requisitos y las decisiones de tu mesa.</p>`,()=>{
   const name=stValue('stFName').trim(),effect=stValue('stFEffect'),dice=stValue('stFDice'),max=stNumber('stFMax'),used=stNumber('stFUsed');if(!name)throw Error('Escribe un nombre.');if(max<0||used<0||max&&used>max)throw Error('Revisa los usos.');if(['damage','heal','temp'].includes(effect)&&!LiorDamage.dice(dice))throw Error('Configura una fórmula de efecto válida.');
   stRequireReady();character.combat_state.development||={};const d=character.combat_state.development;d.features||=[];const updated={...f,id:id||stId(),name,description:stValue('stFDesc'),source:stValue('stFSource'),kind:stValue('stFKind'),resolution:effect==='reference'?'reference':'configured',mechanics:{...m,effect,action:stValue('stFCost'),max,used,recovery:stValue('stFRest'),resource:stValue('stFResource'),cost:stNumber('stFResourceCost'),dice,attack:stNumber('stFAttack'),damage:stNumber('stFDamage'),ac:stNumber('stFAC'),duration:stNumber('stFDuration')}};
   d.features=id?d.features.map(x=>x.id===id?updated:x):d.features.concat(updated);stHistory('Capacidad configurada: '+name);closeModal();stSave();
 });
}

function stOpenLevel(){
 if(Number(character.level)>=20)return toast('Nivel máximo 20 en las reglas 2014. Puedes registrar concesiones del DM sin subir el nivel.');
 Studio.draft={id:stId(),date:stToday(),step:1,classKey:'Brujo',hpMethod:'fixed',hpRoll:5,asiMode:'stats',asi:{dex:1,con:1},invocations:[...(character.combat_state.invocations_known||[])],learn:[],choices:{},notes:'',proficiencies:'',dmOverride:'',subclass:stDev().subclasses?.Brujo||'',base:stSignature(stSnapshot())};stLevelRender();
}
openLevelUpWizard=stOpenLevel;
updateLevel=function(value){document.getElementById('levelSelect').value=character.level;if(Number(value)>Number(character.level))stOpenLevel();else if(Number(value)<Number(character.level))toast('Usa Deshacer subida para revertir una subida completa sin perder la multiclase.');};
function stInvocations(){
 const seen=new Set(ELDRITCH_INVOCATIONS_CATALOG.map(x=>x.id));return ELDRITCH_INVOCATIONS_CATALOG.concat(LiorCatalog.features.filter(x=>x.index.startsWith('eldritch-invocation-')).map(x=>({id:x.index.replace('eldritch-invocation-','').replace(/-/g,'_'),name:x.name,minLevel:x.level,desc:x.desc.join('\n'),reqText:JSON.stringify(x.prerequisites)})).filter(x=>!seen.has(x.id)));
}
function stLevelResult(){const d=Studio.draft;return LiorCharacter.preview(stSnapshot(),{...d,invocationCatalog:stInvocations()},LiorCatalog)}
function stReadLevel(){
 const d=Studio.draft;if(!d)return;
 if(document.getElementById('stLevelClass')){d.classKey=stValue('stLevelClass');d.subclass=stValue('stLevelSubclass');d.dmOverride=stValue('stLevelDM')}
 if(document.getElementById('stLevelHP')){d.hpRoll=stNumber('stLevelHP');d.hpMethod=stValue('stLevelHPMethod');d.asiMode=stValue('stLevelASIMode');d.asi=Object.fromEntries(['str','dex','con','int','wis','cha'].map(k=>[k,stNumber('stASI-'+k)]));const id=stValue('stLevelFeat');d.feat=FEATS_CATALOG_5E.find(f=>f.id===id)||{id:'custom-'+d.id,name:stValue('stLevelFeatName'),desc:stValue('stLevelFeatDesc'),bonusStat:stValue('stLevelFeatStat')||null,bonusVal:stNumber('stLevelFeatBonus')||0};d.notes=stValue('stLevelNotes');d.proficiencies=stValue('stLevelProficiencies')}
 if(document.getElementById('stLevelLearn')){d.learn=[...document.querySelectorAll('#stLevelLearn input:checked')].map(x=>x.value);if(document.getElementById('stLevelInv'))d.invocations=[...document.querySelectorAll('#stLevelInv input:checked')].map(x=>x.value);d.arcanum=stValue('stLevelArc');d.forget=stValue('stLevelForget');for(const group of LiorCharacter.choiceGroups(LiorCatalog,d.classKey,(LiorCharacter.levels(character)[d.classKey]||0)+1,d.subclass)){d.choices[group.id]=[...document.querySelectorAll('[data-st-choice]')].filter(x=>x.dataset.stChoice===group.id&&x.checked).map(x=>x.value)}}
}
function stLevelStep(delta){stReadLevel();Studio.draft.step=Math.max(1,Math.min(4,Studio.draft.step+delta));stLevelRender()}
function stLevelRender(){
 const d=Studio.draft;if(!d)return;const key=d.classKey,n=Number(LiorCharacter.levels(character)[key]||0)+1,info=LiorCharacter.classInfo(LiorCatalog,key),before=LiorCharacter.row(LiorCatalog,key,n-1),after=LiorCharacter.row(LiorCatalog,key,n),asi=(after?.ability_score_bonuses||0)>(before?.ability_score_bonuses||0),features=(after?.features||[]).map(x=>LiorCatalog.features.find(f=>f.index===x.index)).filter(Boolean);
 let content=`<div class="studio-step">Nivel total ${character.level} → ${Number(character.level)+1} · Paso ${d.step}/4 · Borrador sin aplicar</div>`;
 if(d.step===1)content+=`<div class="studio-grid">${stSelect('stLevelClass','Clase que sube de nivel',Object.keys(LiorCharacter.names).map(k=>[k,stClassLabel(k)+' · actual '+Number(LiorCharacter.levels(character)[k]||0)]),key)}${stField('stLevelSubclass','Subclase / especialización',d.subclass)}${stField('stLevelDM','Excepción del DM, si hace falta',d.dmOverride)}</div><p>Nuevo nivel de clase: ${n} · Dado de golpe d${info.hit_die}. Se comprueban los requisitos de todas tus clases al multiclasear. No se conceden las salvaciones ni todo el equipo inicial de una clase nueva.</p><details><summary>Subclase SRD disponible y competencias de multiclase</summary><p>${esc(LiorCatalog.subclasses.filter(s=>s.class.index===LiorCharacter.names[key]).map(s=>s.name+' ['+s.index+']').join(', '))}. Puedes escribir el identificador entre corchetes para incorporar sus rasgos SRD; cualquier otra subclase queda registrada y sus capacidades pueden añadirse con el editor.</p><p>${esc(JSON.stringify(info.multi_classing||{}))}</p></details>`;
 if(d.step===2)content+=`<div class="studio-grid">${stSelect('stLevelHPMethod','Puntos de golpe',[['fixed','Promedio fijo: '+(info.hit_die/2+1)],['manual','Tirada manual d'+info.hit_die]],d.hpMethod)}${stField('stLevelHP','Resultado de la tirada',d.hpRoll,'number',`min="1" max="${info.hit_die}"`)}${stSelect('stLevelASIMode',asi?'Mejora de característica / dote':'Sin mejora de característica en este nivel',[['stats','Distribuir +2 puntos'],['feat','Elegir dote']],d.asiMode)}</div>${asi?`<div class="studio-grid">${['str','dex','con','int','wis','cha'].map(k=>stField('stASI-'+k,k.toUpperCase()+' · actual '+character[k],d.asi[k]||0,'number','min="0" max="2"')).join('')}</div>${stSelect('stLevelFeat','Dote (solo si elegiste dote)',[['custom','Otra dote / suplemento'],...FEATS_CATALOG_5E.map(f=>[f.id,f.name])],d.feat?.id||'custom')}<div class="studio-grid">${stField('stLevelFeatName','Nombre de otra dote',d.feat?.name||'')}${stSelect('stLevelFeatStat','Atributo que aumenta (si corresponde)',[['','Ninguno'],...['str','dex','con','int','wis','cha'].map(k=>[k,k.toUpperCase()])],d.feat?.bonusStat||'')}${stField('stLevelFeatBonus','Aumento de esa dote',d.feat?.bonusVal||0,'number','min="0" max="2"')}</div>${stField('stLevelFeatDesc','Reglas y requisitos de esa dote',d.feat?.desc||'','textarea')}`:['str','dex','con','int','wis','cha'].map(k=>`<input type="hidden" id="stASI-${k}" value="0">`).join('')}<h3>Rasgos de este nivel</h3>${features.map(f=>`<details><summary>${esc(f.name)}</summary><p>${esc(f.desc.join('\n'))}</p></details>`).join('')||'<p>Los beneficios pueden ser mejoras numéricas de rasgos anteriores. Revisa también la tabla de clase del siguiente paso.</p>'}${stField('stLevelNotes','Decisiones: subclase, estilo, pericias, elecciones y reglas de mesa',d.notes,'textarea')}${stField('stLevelProficiencies','Competencias, idiomas o herramientas obtenidos (registro)',d.proficiencies,'textarea')}<p>La Constitución ajusta los PG de niveles anteriores. Las competencias elegidas se registran aquí; asígnalas en Ficha si necesitan un bono concreto.</p>`;
 if(d.step===3){
   const arc=key==='Brujo'?{11:6,13:7,15:8,17:9}[n]:null;
   content+=`<p>Los conjuros se aprenden y preparan por cada clase, no por el nivel conjunto de espacios. El catálogo permite registrar excepciones del DM sin eliminar tus conjuros actuales.</p><details><summary>Tabla del nuevo nivel: magia y recursos</summary><pre>${esc(JSON.stringify({spellcasting:after?.spellcasting,class_specific:after?.class_specific},null,2))}</pre></details><div id="stLevelLearn" class="studio-list"><h3>Conjuros que añadirás a tus conocidos / favoritos</h3>${stLearnChoices(key).map(s=>`<label><input type="checkbox" value="${esc(s.id)}" ${d.learn.includes(s.id)?'checked':''}> ${esc(s.name)} · nivel ${s.level} · ${esc(s.class_origin)}</label>`).join('')||'<p>Todos tus conjuros actuales ya están conocidos.</p>'}</div><p>Puedes incorporar más conjuros desde el catálogo antes de comenzar la subida. La cantidad y elegibilidad se contrastan con la tabla mostrada; no se eliminan conocimientos existentes automáticamente.</p>`;
   if(['Brujo','Bardo','Hechicero','Explorador'].includes(key))content+=stSelect('stLevelForget','Reemplazar un conjuro conocido (opcional)',[['','No reemplazar'],...spells.filter(s=>s.is_known&&Number(s.level)>0).map(s=>[s.id,s.name])],d.forget||'');
   if(key==='Brujo')content+=`<div id="stLevelInv" class="studio-list"><h3>Invocaciones · elige ${after?.class_specific?.invocations_known||0}</h3>${stInvocations().map(i=>`<label title="${esc(i.reqText||i.desc)}"><input type="checkbox" value="${esc(i.id)}" ${d.invocations.includes(i.id)?'checked':''} ${i.minLevel>n?'disabled':''}> ${esc(i.name)} · brujo ${i.minLevel}+</label>`).join('')}</div>`;
   if(arc)content+=stSelect('stLevelArc','Arcanum místico nivel '+arc,[['','Seleccionar'],...spells.filter(s=>Number(s.level)===arc).map(s=>[s.id,s.name])],d.arcanum||'');
   for(const group of LiorCharacter.choiceGroups(LiorCatalog,key,n,d.subclass))content+=`<fieldset class="studio-list"><legend>${esc(group.name)} · elige ${group.choose}</legend>${group.options.map(o=>`<label><input type="checkbox" data-st-choice="${esc(group.id)}" value="${esc(o.index)}" ${(d.choices[group.id]||[]).includes(o.index)?'checked':''}> ${esc(o.name)}</label>`).join('')}</fieldset>`;
 }
 if(d.step===4){try{const p=stLevelResult();Studio.preview=p;content+=`<div class="studio-grid"><div class="studio-summary"><strong>${esc(stClassLabel(key))} ${n}</strong><p>PG máximos ${character.hp_max} → ${p.snapshot.character.hp_max} (${sign(p.hp)})</p><p>Competencia ${sign(LiorCharacter.prof(character.level))} → ${sign(LiorCharacter.prof(Number(character.level)+1))}</p><p>Espacios normales por nivel: ${p.slots.join(' / ')}</p></div><div><p>Conjuros añadidos: ${d.learn.map(id=>esc((id.startsWith('catalog:')?LiorCatalog.spells.find(s=>s.index===id.slice(8)):spells.find(s=>s.id===id))?.name)).join(', ')||'Ninguno'}</p><p>Rasgos registrados: ${p.record.features.map(esc).join(', ')||'Mejoras de la tabla de clase'}</p><p>Acuerdo del DM: ${esc(d.dmOverride||'Sin excepciones')}</p></div></div><p>Al confirmar se aplica una sola actualización al estado compartido y se prepara el guardado en Supabase. No se recuperan recursos gastados por subir de nivel.</p>`}catch(e){Studio.preview=null;content+=`<p role="alert" class="battle-note">${esc(e.message)}</p>`}}
 content+=`<div class="studio-actions">${d.step>1?'<button class="quiet-btn" id="stLevelBack">← Anterior</button>':''}${d.step<4?'<button class="gold-btn" id="stLevelNext">Siguiente →</button>':''}<button class="quiet-btn" id="stLevelCancel">Cancelar sin aplicar</button></div>`;
 stModal('Desarrollo del personaje · D&D 5e 2014',content,d.step===4&&Studio.preview?stCommitLevel:null);
 document.getElementById('stLevelBack')?.addEventListener('click',()=>stLevelStep(-1));document.getElementById('stLevelNext')?.addEventListener('click',()=>stLevelStep(1));document.getElementById('stLevelCancel').onclick=()=>{Studio.draft=null;closeModal()};
 document.getElementById('stLevelClass')?.addEventListener('change',()=>{stReadLevel();d.subclass=stDev().subclasses?.[d.classKey]||'';d.hpRoll=LiorCharacter.classInfo(LiorCatalog,d.classKey).hit_die/2+1;stLevelRender()});
}
function stCommitLevel(){
 stRequireReady();const d=Studio.draft;if(!d)throw Error('La subida ya fue aplicada.');if(stSignature(stSnapshot())!==d.base)throw Error('La ficha cambió durante la revisión. Cancela y vuelve a abrir la subida con los datos actuales.');
 const before=stSnapshot(),result=stLevelResult();Studio.undo={before,after:stSignature(result.snapshot),record:result.record.id};
 character=result.snapshot.character;inventory=result.snapshot.inventory;spells=result.snapshot.spells;companions=result.snapshot.companions;logs=result.snapshot.logs;Studio.draft=null;closeModal();stSave();toast('Nivel aplicado. Revisa el indicador de guardado de Supabase.');
}
undoLevel=function(){
 try{stRequireReady();if(!Studio.undo)return toast('Solo puedes deshacer la subida de esta sesión.');if(stSignature(stSnapshot())!==Studio.undo.after)return toast('La ficha cambió después de subir. No se sobrescribirán cambios posteriores.');if(!confirm('¿Deshacer la última subida completa?'))return;const stamp=character.updated_at,s=Studio.undo.before;character=s.character;character.updated_at=stamp;inventory=s.inventory;spells=s.spells;companions=s.companions;logs=s.logs;Studio.undo=null;stSave()}catch(e){toast(e.message)}
};

function renderStudio(){
 const host=document.getElementById('characterStudio');if(!host)return;const d=stDev(),ls=LiorCharacter.levels(character),max=LiorCharacter.slotMaximum(character);
 host.innerHTML=`<div class="ready-heading"><div><span class="eyebrow">Ficha completa · reglas 2014 y acuerdos de mesa</span><h2>Desarrollo de Lior</h2></div><button class="gold-btn" onclick="stOpenLevel()">Subir de nivel</button></div><p>${Object.entries(ls).map(([k,v])=>esc(stClassLabel(k))+' '+v).join(' / ')} · Nivel total ${character.level} · Competencia ${sign(LiorCharacter.prof(character.level))}</p><div class="studio-actions"><button class="quiet-btn" onclick="stCatalog()">Catálogos de todas las clases</button><button class="quiet-btn" onclick="openSpellModal()">Conjuro del DM</button><button class="quiet-btn" onclick="openItemModal()">Arma / objeto del DM</button><button class="quiet-btn" onclick="stFeatureEditor()">Rasgo / dote / competencia</button><button class="quiet-btn" onclick="stResourceEditor()">Reserva / cargas</button><button class="quiet-btn" onclick="undoLevel()">Deshacer subida</button></div><h3>Espacios normales · separados de Magia del Pacto</h3><div class="studio-slot-row">${max.map((n,i)=>n?`<span class="condition-mark">Nivel ${i+1}: ${Math.max(0,n-Number(d.spellSlotsUsed?.[i]||0))} / ${n}</span>`:'').join('')||'<p>Sin espacios de lanzamiento normales. Los de brujo siguen en Magia del Pacto.</p>'}</div><details><summary>Subclases y lanzamiento de tercio de nivel</summary><p>Para Caballero Arcano o Embaucador Arcano, activa el cómputo de espacios de esa subclase. Las demás reglas de subclase se registran como capacidades.</p>${['Guerrero','Picaro'].map(k=>`<label class="dc-toggle"><input type="checkbox" onchange="stThirdCaster('${k}',this.checked)" ${d.thirdCasters?.includes(k)?'checked':''}> ${esc(stClassLabel(k))}: lanzamiento de un tercio</label>`).join('')}<p>${Object.entries(d.subclasses||{}).map(([k,v])=>esc(stClassLabel(k)+': '+v)).join(' · ')||'Subclases anteriores conservadas en los datos originales de la ficha.'}</p></details><h3>Dados de golpe por clase</h3><p>Se gastan durante un descanso corto. El descanso largo recupera hasta la mitad de tu nivel total, primero los dados de mayor tamaño.</p><div class="studio-actions">${Object.entries(ls).map(([key,level])=>`<button class="quiet-btn" onclick="stHitDie('${key}')">${esc(stClassLabel(key))} · ${Math.max(0,level-Number(d.hitDiceUsed?.[key]||0))}/${level} d${LiorCharacter.classInfo(LiorCatalog,key)?.hit_die||8}</button>`).join('')}</div><h3>Reservas y concesiones</h3>${(d.resources||[]).map(r=>`<article class="studio-row"><div><strong>${esc(r.name)}</strong><p>${Math.max(0,r.max-Number(r.used||0))} / ${r.max} · ${esc(r.recovery)}</p></div><button class="quiet-btn" data-st-resource="${esc(r.id)}">Editar / corregir</button></article>`).join('')||'<p>No has añadido reservas personalizadas.</p>'}<div id="stFeatureList"></div><details><summary>Historial de concesiones y cambios</summary>${(d.history||[]).slice(0,40).map(h=>`<p>${esc(h.date)} · ${esc(h.text)}</p>`).join('')||'<p>Aquí se registrarán las nuevas concesiones.</p>'}</details>`;
 document.querySelectorAll('[data-st-resource]').forEach(b=>b.onclick=()=>stResourceEditor(b.dataset.stResource));
 const featureHTML=(d.features||[]).map(f=>`<article class="studio-row"><div><strong>${esc(f.name)}</strong><small>${esc(f.source)} · ${f.resolution==='configured'?'Efecto configurado':'Referencia: se resuelve en mesa'}</small><details><summary>Descripción y requisitos</summary><p>${esc(f.description)}</p></details></div><button class="quiet-btn" data-st-feature="${esc(f.id)}">Configurar</button></article>`).join('')||'<p>Las capacidades originales siguen en sus apartados. Aquí aparecerán las obtenidas en nuevas subidas y las concedidas por el DM.</p>';
 document.getElementById('stFeatureList').innerHTML=featureHTML;document.querySelectorAll('[data-st-feature]').forEach(b=>b.onclick=()=>stFeatureEditor(b.dataset.stFeature));
 renderStudioCombat();
}
function stThirdCaster(key,on){try{stRequireReady();character.combat_state.development||={};const d=character.combat_state.development;d.thirdCasters||=[];d.thirdCasters=d.thirdCasters.filter(k=>k!==key);if(on)d.thirdCasters.push(key);stHistory('Lanzamiento de subclase: '+key+' '+on);stSave()}catch(e){toast(e.message)}}
const studioPreviousAll=renderAll;renderAll=function(){studioPreviousAll();renderStudio()};
document.addEventListener('DOMContentLoaded',()=>{
 const host=document.createElement('section');host.id='characterStudio';host.className='panel studio-panel';document.getElementById('tab-progression').prepend(host);
 const battle=document.createElement('section');battle.id='studioCombat';battle.className='battle-panel studio-panel';document.getElementById('battleDesk').append(battle);
 const button=document.createElement('button');button.className='quiet-btn';button.textContent='Catálogo de todas las clases';button.onclick=()=>stCatalog();document.getElementById('tab-spells').prepend(button);
 const gear=document.createElement('button');gear.className='quiet-btn';gear.textContent='Catálogo SRD y equipo del DM';gear.onclick=()=>stCatalog('equipment');document.getElementById('tab-equipment').prepend(gear);
 renderStudio();
});

function stLearnChoices(key){const cls=LiorCharacter.names[key];return spells.filter(s=>!s.is_known).concat(LiorCatalog.spells.filter(s=>s.classes.some(c=>c.index===cls)&&!stExistingSpell(s.index,s.name)).map(s=>({id:'catalog:'+s.index,name:s.name,level:s.level,class_origin:s.classes.map(c=>c.name).join('/')}))).sort((a,b)=>Number(a.level)-Number(b.level)||a.name.localeCompare(b.name))}

/* ===== guided-progression ===== */
/* Guided progression: current sheet first, only next-level choices in the builder. */
const ProgressFlow={page:1,query:''};
function pgInvocations(plan){return stInvocations().filter(inv=>{if(Studio.draft.invocations.includes(inv.id))return true;if(inv.minLevel>plan.level)return false;const ref=LiorCatalog.features.find(f=>f.index==='eldritch-invocation-'+inv.id.replace(/_/g,'-'));const pact=stDev().pact||'blade';for(const req of ref?.prerequisites||[]){if(req.feature?.includes('pact-of-the-tome')&&pact!=='tome')return false;if(req.feature?.includes('pact-of-the-chain')&&pact!=='chain')return false;if(req.feature?.includes('pact-of-the-blade')&&pact!=='blade')return false;if(req.spell?.includes('eldritch-blast')&&!spells.some(s=>s.is_known&&/descarga sobrenatural|eldritch blast/i.test(s.name)))return false}return true})}
function pgPlan(key){
 const current=Number(LiorCharacter.levels(character)[key]||0),level=current+1,before=LiorCharacter.row(LiorCatalog,key,current),after=LiorCharacter.row(LiorCatalog,key,level),info=LiorCharacter.classInfo(LiorCatalog,key);
 const max=Math.max(0,...Object.entries(after?.spellcasting||{}).filter(([k,v])=>k.startsWith('spell_slots_level_')&&v>0).map(([k])=>Number(k.split('_').pop())));
 const known=Math.max(0,Number(after?.spellcasting?.spells_known||0)-Number(before?.spellcasting?.spells_known||0));
 const prepared=['Clerigo','Druida','Paladin'].includes(key)&&max>0,preparationLimit=Math.max(1,getMod(character[LiorCharacter.abilities[key]||'int'])+(key==='Paladin'?Math.floor(level/2):level));
 return{key,current,level,info,before,after,max,prepared,preparationLimit,spells:prepared?preparationLimit:key==='Mago'?(current?2:6):known,cantrips:Math.max(0,Number(after?.spellcasting?.cantrips_known||0)-Number(before?.spellcasting?.cantrips_known||0)),asi:Number(after?.ability_score_bonuses||0)>Number(before?.ability_score_bonuses||0),invocations:key==='Brujo'?Number(after?.class_specific?.invocations_known||0):null,arc:key==='Brujo'?{11:6,13:7,15:8,17:9}[level]:null};
}
function pgKnown(sp,key){return sp.is_known&&(sp.learned_class?sp.learned_class===key:sp.mechanics?.source?.startsWith(stClassLabel(key))||key==='Brujo')}
function pgCandidates(key,atLevel=null){
 const p=pgPlan(key),list=[],seen=new Set();if(atLevel!==null){const row=LiorCharacter.row(LiorCatalog,key,atLevel);p.max=Math.max(0,...Object.entries(row?.spellcasting||{}).filter(([k,v])=>k.startsWith('spell_slots_level_')&&v>0).map(([k])=>Number(k.split('_').pop())));p.prepared=true;}
 for(const original of spells){
  const ref=stSpellReference(original),origin=(original.class_origin||'').toLowerCase();
  const belongs=ref?ref.classes.some(c=>c.index===LiorCharacter.names[key]):[key,stClassLabel(key),LiorCharacter.names[key]].some(k=>origin.includes(k.toLowerCase()))||key==='Brujo'&&origin.includes('filo maléfico');
  if(!belongs||Number(original.level)>p.max||pgKnown(original,key)&&!(p.prepared&&Number(original.level)>0))continue;
  const copy=original.is_known&&!pgKnown(original,key)?{...LiorCharacter.clone(original),id:'class-'+key+'-'+original.id,name:original.name+' · '+stClassLabel(key),is_known:false,is_equipped:false,learned_class:key,mechanics:{...original.mechanics,ability:LiorCharacter.abilities[key]||'int',pool:'auto',source:stClassLabel(key)+' '+p.level}}:null;
  list.push({id:copy?.id||original.id,name:original.name,level:Number(original.level),description:original.description||'',copy});if(ref)seen.add(ref.index);
 }
 for(const sp of LiorCatalog.spells.filter(sp=>sp.classes.some(c=>c.index===LiorCharacter.names[key])&&sp.level<=p.max)){
  if(seen.has(sp.index)||spells.some(s=>pgKnown(s,key)&&(s.catalog_index===sp.index||s.name.toLowerCase()===sp.name.toLowerCase()||s.name.toLowerCase().includes('('+sp.name.toLowerCase()+')'))))continue;
  list.push({id:'catalog:'+sp.index,name:sp.name,level:sp.level,description:sp.desc.join('\n')});
 }
 return list.sort((a,b)=>a.level-b.level||a.name.localeCompare(b.name));
}
function pgSnapshot(){const s=stSnapshot(),d=Studio.draft;for(const candidate of pgCandidates(d.classKey))if(candidate.copy&&d.learn.includes(candidate.id)&&!s.spells.some(sp=>sp.id===candidate.id))s.spells.push(LiorCharacter.clone(candidate.copy));return s}
stLevelResult=function(){const d=Studio.draft,p=pgPlan(d.classKey),r=LiorCharacter.preview(pgSnapshot(),{...d,invocationCatalog:stInvocations()},LiorCatalog),candidates=pgCandidates(d.classKey);for(const sp of r.snapshot.spells){const selected=d.learn.includes(sp.id)||d.learn.includes('catalog:'+sp.catalog_index);if(selected){sp.learned_class=d.classKey;sp.mechanics||={};sp.mechanics.ability=LiorCharacter.abilities[d.classKey]||sp.mechanics.ability||'int'}if(p.prepared&&sp.learned_class===d.classKey&&Number(sp.level)>0){sp.mechanics||={};sp.mechanics.requiresPreparation=true;sp.mechanics.prepared=selected;sp.is_equipped=selected}if(d.classKey==='Mago'&&sp.learned_class==='Mago'&&Number(sp.level)>0){sp.mechanics||={};sp.mechanics.requiresPreparation=true;const already=r.snapshot.spells.filter(s=>s.learned_class==='Mago'&&s.mechanics?.prepared&&s.id!==sp.id).length;if(sp.mechanics.prepared===undefined)sp.mechanics.prepared=already<p.preparationLimit;sp.is_equipped=sp.mechanics.prepared}}
return r};
function pgStart(key='Brujo'){
 if(typeof key!=='string'||!LiorCharacter.names[key])key='Brujo';
 if(character.level>=20)return toast('Tu personaje ha alcanzado el nivel máximo de 2014.');
 const p=pgPlan(key);ProgressFlow.page=1;ProgressFlow.query='';
 Studio.draft={id:stId(),date:stToday(),classKey:key,hpMethod:'fixed',hpRoll:p.info.hit_die/2+1,asiMode:'stats',asi:{dex:1,con:1},invocations:[...(character.combat_state.invocations_known||[])],learn:[],choices:{},notes:'',proficiencies:'',dmOverride:'',subclass:stDev().subclasses?.[key]||'',base:stSignature(stSnapshot())};pgRender();
}
stOpenLevel=pgStart;openLevelUpWizard=pgStart;
function pgRead(){
 const d=Studio.draft;if(!d)return;
 if(document.getElementById('pgClass')){d.classKey=stValue('pgClass');d.hpMethod=stValue('pgHPMethod');d.hpRoll=stNumber('pgHP');d.subclass=stValue('pgSubclass')||d.subclass;d.dmOverride=stValue('pgDM')}
 if(document.getElementById('pgAsiMode')){d.asiMode=stValue('pgAsiMode');d.asi={};for(const id of ['pgStatA','pgStatB']){const stat=stValue(id);if(stat)d.asi[stat]=(d.asi[stat]||0)+1}d.feat=FEATS_CATALOG_5E.find(f=>f.id===stValue('pgFeat'))}
 if(document.getElementById('pgInvocations'))d.invocations=[...document.querySelectorAll('#pgInvocations input:checked')].map(x=>x.value);
 if(document.getElementById('pgArcanum'))d.arcanum=stValue('pgArcanum');
 for(const g of LiorCharacter.choiceGroups(LiorCatalog,d.classKey,pgPlan(d.classKey).level,d.subclass)){
  const select=document.getElementById('pgChoice-'+g.id);if(select)d.choices[g.id]=[...select.selectedOptions].map(o=>o.value).filter(Boolean);
 }
}
function pgSpellChoice(id,on){const d=Studio.draft,candidates=pgCandidates(d.classKey),selected=candidates.find(x=>x.id===id);if(!selected)return;const p=pgPlan(d.classKey),limit=selected.level===0?p.cantrips:p.spells,current=d.learn.filter(id=>candidates.find(x=>x.id===id)?.level===0===(selected.level===0));if(on&&current.length>=limit){toast('Ya elegiste los '+limit+' '+(selected.level===0?'trucos':'conjuros')+' de esta subida. Desmarca uno para cambiarlo.');return false}d.learn=d.learn.filter(x=>x!==id);if(on)d.learn.push(id);return true}
function pgValidate(){const p=pgPlan(Studio.draft.classKey),candidates=pgCandidates(p.key),chosen=Studio.draft.learn.map(id=>candidates.find(x=>x.id===id)).filter(Boolean);if(chosen.filter(s=>s.level===0).length!==p.cantrips)throw Error('Elige '+p.cantrips+' truco(s) nuevo(s).');if(chosen.filter(s=>s.level>0).length!==p.spells)throw Error('Elige '+p.spells+' conjuro(s) nuevo(s).');return stLevelResult()}
function pgRender(){
 const d=Studio.draft;if(!d)return;const p=pgPlan(d.classKey),page=ProgressFlow.page;let html=`<div class="pg-progress"><strong>${character.name} · ${character.level} → ${Number(character.level)+1}</strong><span>${page===1?'1 · Clase y beneficios':page===2?'2 · Tus elecciones':'3 · Revisar y confirmar'}</span></div>`;
 if(page===1){
  html+=`<div class="studio-grid">${stSelect('pgClass','¿En qué clase quieres avanzar?',Object.keys(LiorCharacter.names).map(k=>[k,stClassLabel(k)+' · nivel '+(Number(LiorCharacter.levels(character)[k]||0)+1)]),d.classKey)}${stSelect('pgHPMethod','Puntos de golpe',[['fixed','Valor fijo: '+(p.info.hit_die/2+1)+' + Constitución'],['manual','Tirar 1d'+p.info.hit_die+' + Constitución']],d.hpMethod)}${d.hpMethod==='manual'?stField('pgHP','Resultado del dado',d.hpRoll,'number',`min="1" max="${p.info.hit_die}"`):`<input type="hidden" id="pgHP" value="${d.hpRoll}">`}</div><div class="pg-benefits"><h3>Esto cambia al llegar a ${stClassLabel(d.classKey)} ${p.level}</h3><p>＋ ${Math.max(1,(p.info.hit_die/2+1)+getMod(character.con))} PG con valor fijo · 1 dado de golpe d${p.info.hit_die}</p>${p.after.features.map(f=>`<details><summary>${esc(f.name)}</summary><p>${esc(LiorCatalog.features.find(x=>x.index===f.index)?.desc.join('\n')||'')}</p></details>`).join('')}${p.max?'<p>Magia disponible de esta clase: hasta nivel '+p.max+'. Los espacios se calculan al confirmar.</p>':''}${p.spells||p.cantrips?'<p>Vas a elegir '+p.spells+' conjuro(s) y '+p.cantrips+' truco(s).</p>':'<p>No necesitas elegir conjuros o trucos nuevos en este nivel.</p>'}${p.asi?'<p>Podrás mejorar características o elegir una dote.</p>':''}</div><details><summary>Excepción del DM o subclase de otro suplemento</summary>${stField('pgSubclass','Subclase (conserva la actual si no cambia)',d.subclass)}${stField('pgDM','Acuerdo del DM',d.dmOverride)}<p>Estas opciones son para excepciones de la mesa. La selección normal del siguiente paso se ajusta a tu clase y nivel.</p></details>`;
 }
 if(page===2){
  if(p.asi)html+=`<h3>Mejora de característica</h3><div class="studio-grid">${stSelect('pgAsiMode','Cómo quieres mejorar',[['stats','Dos puntos de característica'],['feat','Una dote']],d.asiMode)}${stSelect('pgStatA','Primer punto',['str','dex','con','int','wis','cha'].map(k=>[k,k.toUpperCase()+' · '+character[k]]),Object.keys(d.asi)[0]||'dex')}${stSelect('pgStatB','Segundo punto',['str','dex','con','int','wis','cha'].map(k=>[k,k.toUpperCase()+' · '+character[k]]),Object.keys(d.asi)[1]||Object.keys(d.asi)[0]||'con')}${stSelect('pgFeat','Dote (si elegiste dote)',FEATS_CATALOG_5E.filter(f=>!character.combat_state.feats?.includes(f.id)).map(f=>[f.id,f.name]),d.feat?.id||'war_caster')}</div>`;
  if(p.invocations!==null){html+=`<h3>Invocaciones · ${d.invocations.length}/${p.invocations}</h3><p>Conservas tus invocaciones. Marca la nueva o cambia una elección.</p><div id="pgInvocations" class="studio-list">${pgInvocations(p).map(i=>`<label><input type="checkbox" value="${esc(i.id)}" ${d.invocations.includes(i.id)?'checked':''}> <span>${esc(i.name)}</span></label><details><summary>Qué hace</summary><p>${esc(i.desc)}</p></details>`).join('')}</div>`}
  if(p.spells||p.cantrips)html+=`<h3>Magia de ${stClassLabel(d.classKey)}</h3><p>Solo aparecen opciones de tu clase que ya puedes aprender. Tu configuración actual se conserva.</p>${stField('pgSpellSearch','Buscar conjuro o truco',ProgressFlow.query,'search')}<div id="pgSpellCounter"></div><div id="pgSpells" class="pg-spell-list"></div>`;
  if(p.arc)html+=stSelect('pgArcanum','Arcanum místico · nivel '+p.arc,[['','Seleccionar'],...spells.filter(s=>Number(s.level)===p.arc).map(s=>[s.id,s.name])],d.arcanum||'');
  for(const g of LiorCharacter.choiceGroups(LiorCatalog,p.key,p.level,d.subclass))html+=`<label>${esc(g.name)} · elige ${g.choose}<select id="pgChoice-${esc(g.id)}" ${g.choose>1?'multiple':''}>${g.choose===1?'<option value="">Seleccionar</option>':''}${g.options.map(o=>`<option value="${esc(o.index)}" ${(d.choices[g.id]||[]).includes(o.index)?'selected':''}>${esc(o.name)}</option>`).join('')}</select></label>`;
  if(!p.asi&&!p.spells&&!p.cantrips&&!p.invocations&&!LiorCharacter.choiceGroups(LiorCatalog,p.key,p.level,d.subclass).length)html+='<p>Los beneficios de este nivel se calculan automáticamente. No quedan elecciones pendientes.</p>';
 }
 let result=null;if(page===3){try{result=pgValidate();html+=`<div class="pg-benefits"><h3>${esc(result.snapshot.character.class_name)}</h3><p>PG máximos: ${character.hp_max} → <strong>${result.snapshot.character.hp_max}</strong></p><p>Competencia: ${sign(LiorCharacter.prof(character.level))} → ${sign(LiorCharacter.prof(Number(character.level)+1))}</p><p>Selecciones de magia: ${d.learn.length}</p>${d.classKey==='Brujo'?'<p>Magia del Pacto: '+getWarlockProgression(p.level).slotCount+' espacios de nivel '+getWarlockProgression(p.level).slotLevel+'.</p>':''}<p>Espacios normales: ${result.slots.filter(n=>n>0).join(' / ')||'Ninguno; Pacto se conserva separado'}</p><p>Los recursos gastados conservan su gasto al subir de nivel.</p></div>`}catch(e){html+=`<p class="battle-note" role="alert">${esc(e.message)}</p>`}}
 html+=`<div class="studio-actions">${page>1?'<button class="quiet-btn" id="pgBack">← Atrás</button>':''}${page<3?'<button class="gold-btn" id="pgNext">'+(page===1?'Elegir mis mejoras →':'Revisar subida →')+'</button>':''}</div>`;
 stModal('Subir de nivel · '+stClassLabel(d.classKey),html,page===3&&result?stCommitLevel:null);if(page===3&&result)document.getElementById('modalSaveBtn').textContent='Confirmar nivel '+(Number(character.level)+1);
 document.getElementById('pgClass')?.addEventListener('change',e=>pgStart(e.target.value));document.getElementById('pgHPMethod')?.addEventListener('change',()=>{pgRead();pgRender()});
 document.getElementById('pgNext')?.addEventListener('click',()=>{pgRead();ProgressFlow.page++;pgRender()});document.getElementById('pgBack')?.addEventListener('click',()=>{pgRead();ProgressFlow.page--;pgRender()});
 document.getElementById('pgSpellSearch')?.addEventListener('input',e=>{ProgressFlow.query=e.target.value;pgSpellRows()});pgSpellRows();
}
function pgSpellRows(){
 const host=document.getElementById('pgSpells');if(!host)return;const d=Studio.draft,p=pgPlan(d.classKey),all=pgCandidates(d.classKey),chosen=d.learn.map(id=>all.find(s=>s.id===id)).filter(Boolean),q=ProgressFlow.query.trim().toLowerCase();
 document.getElementById('pgSpellCounter').textContent='Trucos '+chosen.filter(s=>s.level===0).length+'/'+p.cantrips+' · Conjuros '+chosen.filter(s=>s.level>0).length+'/'+p.spells;
 host.innerHTML=all.filter(s=>(s.level===0?p.cantrips>0:p.spells>0)&&(!q||(s.name+' '+s.description).toLowerCase().includes(q))).map(s=>`<div class="pg-spell"><label><input type="checkbox" value="${esc(s.id)}" ${d.learn.includes(s.id)?'checked':''}><span><strong>${esc(s.name)}</strong><small>${s.level===0?'Truco':'Nivel '+s.level}</small></span></label><details><summary>Qué hace</summary><p>${esc(s.description)}</p></details></div>`).join('')||'<p>No hay coincidencias.</p>';
 host.querySelectorAll('input').forEach(el=>el.onchange=()=>{pgSpellChoice(el.value,el.checked);pgSpellRows()});
}
renderStudio=function(){
 const host=document.getElementById('characterStudio');if(!host)return;const levels=LiorCharacter.levels(character),d=stDev(),known=spells.filter(s=>s.is_known),features=[];
 for(const [key,level]of Object.entries(levels))for(let n=1;n<=level;n++)for(const f of LiorCharacter.row(LiorCatalog,key,n)?.features||[])if(!features.some(x=>x.index===f.index))features.push({...f,source:stClassLabel(key)+' '+n});
 host.innerHTML=`<div class="pg-current"><div><span class="eyebrow">Tu personaje ahora</span><h2>${esc(character.name)}</h2><p>${Object.entries(levels).map(([k,n])=>esc(stClassLabel(k))+' '+n).join(' / ')} · Nivel total ${character.level}</p></div><button class="gold-btn" onclick="pgStart()">Subir a nivel ${Number(character.level)+1} →</button></div><div class="pg-current-stats"><span><strong>${character.hp_max}</strong> PG máximos</span><span><strong>${sign(LiorCharacter.prof(character.level))}</strong> Competencia</span><span><strong>${known.filter(s=>Number(s.level)===0).length}</strong> Trucos actuales</span><span><strong>${known.filter(s=>Number(s.level)>0).length}</strong> Conjuros y concesiones</span></div><h3>Lo que ya tienes</h3><div class="studio-grid"><div><h3>Invocaciones</h3>${(character.combat_state.invocations_known||[]).map(id=>{const inv=stInvocations().find(x=>x.id===id);return '<details><summary>'+esc(inv?.name||id)+'</summary><p>'+esc(inv?.desc||'Regla registrada por tu mesa.')+'</p></details>'}).join('')}</div><div><h3>Rasgos de tus clases</h3>${features.map(f=>`<details><summary>${esc(f.name)} <small>· ${esc(f.source)}</small></summary><p>${esc(LiorCatalog.features.find(x=>x.index===f.index)?.desc.join('\n')||'')}</p></details>`).join('')}</div></div><details><summary>Historial de niveles</summary>${(character.combat_state.level_history||[]).map(h=>'<p>'+esc(stClassLabel(h.class))+' · '+h.from+' → '+h.to+' · '+sign(h.hp)+' PG</p>').join('')||'<p>Las nuevas subidas quedarán registradas aquí.</p>'}<button class="quiet-btn" onclick="undoLevel()">Deshacer última subida de esta sesión</button></details><details><summary>Concesiones del DM y ajustes de la ficha</summary><p>Para lo que obtengas fuera de la progresión normal de tus clases.</p><div class="studio-actions"><button class="quiet-btn" onclick="stCatalog()">Consultar catálogos</button><button class="quiet-btn" onclick="openSpellModal()">Añadir conjuro concedido</button><button class="quiet-btn" onclick="openItemModal()">Añadir equipo</button><button class="quiet-btn" onclick="stFeatureEditor()">Añadir capacidad o dote</button><button class="quiet-btn" onclick="stResourceEditor()">Configurar reserva</button></div>${(d.features||[]).map(f=>`<article class="studio-row"><div><strong>${esc(f.name)}</strong><small>${esc(f.source)}</small></div><button class="quiet-btn" data-pg-feature="${esc(f.id)}">Configurar</button></article>`).join('')}${(d.resources||[]).map(r=>`<article class="studio-row"><span>${esc(r.name)} · ${r.max-Number(r.used||0)}/${r.max}</span><button class="quiet-btn" data-pg-resource="${esc(r.id)}">Editar</button></article>`).join('')}</details>`;
 host.querySelectorAll('[data-pg-feature]').forEach(b=>b.onclick=()=>stFeatureEditor(b.dataset.pgFeature));host.querySelectorAll('[data-pg-resource]').forEach(b=>b.onclick=()=>stResourceEditor(b.dataset.pgResource));renderStudioCombat();
};
document.addEventListener('DOMContentLoaded',()=>{document.body.classList.add('pg-guided');renderStudio()});
function pgPrepare(key=null){
 const available=Object.keys(LiorCharacter.levels(character)).filter(k=>['Mago','Clerigo','Druida','Paladin'].includes(k)&&LiorCharacter.levels(character)[k]>=(k==='Paladin'?2:1));
 if(!available.length)return toast('Tus clases actuales no necesitan preparación diaria de conjuros.');
 if(!key){if(available.length===1)return pgPrepare(available[0]);stModal('Preparar conjuros',stSelect('pgPrepareClass','Clase',available.map(k=>[k,stClassLabel(k)]),available[0]),()=>{const selected=stValue('pgPrepareClass');pgPrepare(selected)});return}
 const level=LiorCharacter.levels(character)[key],limit=Math.max(1,getMod(character[LiorCharacter.abilities[key]])+(key==='Paladin'?Math.floor(level/2):level));
 const all=key==='Mago'?spells.filter(s=>s.learned_class==='Mago'&&Number(s.level)>0).map(s=>({id:s.id,name:s.name,level:s.level,description:s.description})):pgCandidates(key,level).filter(s=>s.level>0);
 const stamp=stSignature(stSnapshot());
 stModal('Preparación de '+stClassLabel(key),`<p>Elige hasta ${limit} conjuros. Preparar conserva tus espacios y los usos que ya gastaste.</p><div class="pg-spell-list" id="pgPrepareList">${all.map(s=>`<label class="pg-spell"><input type="checkbox" value="${esc(s.id)}" ${spells.find(x=>x.id===s.id)?.mechanics?.prepared?'checked':''}> ${esc(s.name)} · nivel ${s.level}</label>`).join('')}</div>`,()=>{
  stRequireReady();if(stSignature(stSnapshot())!==stamp)throw Error('La ficha cambió mientras preparabas. Vuelve a abrir la preparación.');const selected=[...document.querySelectorAll('#pgPrepareList input:checked')].map(x=>x.value);if(selected.length>limit)throw Error('El máximo para esta clase es '+limit+'.');
  const next=LiorCharacter.clone(spells);for(const sp of next)if(sp.learned_class===key&&Number(sp.level)>0){sp.mechanics||={};sp.mechanics.requiresPreparation=true;sp.mechanics.prepared=false;sp.is_equipped=false}
  for(const id of selected){const candidate=all.find(s=>s.id===id);let sp=next.find(s=>s.id===id);if(!sp){sp=id.startsWith('catalog:')?LiorCharacter.catalogSpell(LiorCatalog,id.slice(8),key,stId()):LiorCharacter.clone(candidate.copy);next.push(sp)}sp.learned_class=key;sp.is_known=true;sp.is_equipped=true;sp.mechanics={...sp.mechanics,ability:LiorCharacter.abilities[key],pool:'auto',requiresPreparation:true,prepared:true,source:stClassLabel(key)+' '+level}}
  spells=next;stHistory('Preparación de '+stClassLabel(key)+': '+selected.length+' conjuros');closeModal();stSave();
 });
}
const pgPreviousSpells=renderSpellsTab;renderSpellsTab=function(){pgPreviousSpells();const tab=document.getElementById('tab-spells');if(tab&&!document.getElementById('pgPrepareButton')){const b=document.createElement('button');b.id='pgPrepareButton';b.className='quiet-btn';b.textContent='Preparar conjuros de mis clases';b.onclick=()=>pgPrepare();tab.prepend(b)}};

const pgOldCloseModal=closeModal;closeModal=function(){Studio.draft=null;pgOldCloseModal()};
